mapper.update:
UPDATE t_chat_message
   SET is_read = 1
 WHERE to_user_id = #{uid}
   AND from_user_id = #{peerId}
   AND is_read = 0

mapper.select:
SELECT m.id AS id, m.from_user_id AS from_user_id, fu.nickname AS from_nickname, m.to_user_id AS to_user_id, m.content AS content, m.created_at AS created_at FROM t_chat_message m LEFT JOIN t_user fu ON fu.id = m.from_user_id WHERE ((m.from_user_id = #{userA} AND m.to_user_id = #{userB}) OR (m.from_user_id = #{userB} AND m.to_user_id = #{userA}))
AND m.item_id = #{itemId}
ORDER BY m.created_at ASC, m.id ASC
